import { Router } from 'express';
import { z } from 'zod';
import { getInvoiceList, exportInvoices } from '../services/invoiceService';
import { audit } from '../middleware/audit';

const router = Router();

const listQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(50),
  status: z.enum(['draft', 'sent', 'paid', 'void']).optional(),
  sort: z.enum(['date', 'amount', 'status']).default('date'),
});

export async function listInvoices(req, res) {
  const parsed = listQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ error: 'invalid_query', details: parsed.error.flatten() });
  }
  const { page, pageSize, status, sort } = parsed.data;
  try {
    const result = await getInvoiceList(req.customerId, page, pageSize, { status, sort });
    return res.json({
      data: result.invoices,
      pagination: {
        page: result.page,
        pageSize: result.pageSize,
        total: result.total,
        hasMore: result.hasMore,
      },
    });
  } catch (err) {
    req.log.error({ err }, 'listInvoices failed');
    return res.status(500).json({ error: 'internal' });
  }
}

