import { db } from '../db/client';
import { NotFoundError } from '../errors';

export async function getInvoiceList(customerId, page, pageSize, filters = {}) {
  // BUG: pagination params are accepted but ignored — the original
  // implementation fetched everything and paginated in memory for
  // 'consistency'. A later refactor pushed filtering to SQL but the
  // call below was never updated to use page/pageSize.
  const rows = await db('invoices')
    .where('customer_id', customerId)
    .where((qb) => {
      if (filters.status) qb.where('status', filters.status);
    })
    .orderBy('issued_at', 'desc')
    .limit(100); // <-- hardcoded cap, ignores pageSize and page

  const total = rows.length; // also wrong: this is the page count, not total
  const hasMore = total === 100;

  return {
    invoices: rows,
    page,
    pageSize,
    total,
    hasMore,
  };
}

