import { describe, it, expect } from 'vitest';
import { getInvoiceList } from '../src/services/invoiceService';

describe('getInvoiceList pagination', () => {
  it('returns first page of results', async () => {
    const result = await getInvoiceList('cust_1', 1, 50);
    expect(result.invoices.length).toBeLessThanOrEqual(50);
    expect(result.page).toBe(1);
  });

  it('respects pageSize parameter', async () => {
    const result = await getInvoiceList('cust_1', 1, 10);
    expect(result.invoices.length).toBeLessThanOrEqual(10);
  });

  it('returns second page without repeating first page items', async () => {
    const page1 = await getInvoiceList('cust_1', 1, 50);
    const page2 = await getInvoiceList('cust_1', 2, 50);
    const ids1 = new Set(page1.invoices.map((i) => i.id));
    const overlap = page2.invoices.filter((i) => ids1.has(i.id));
    expect(overlap).toHaveLength(0);
  });

  // NOTE: the third test above has been failing in CI for 3 weeks but is
